package com.bankease.service;
import com.bankease.dto.AuthDtos.*; import com.bankease.entity.*; import com.bankease.repository.UserRepository; import com.bankease.security.JwtService; import org.springframework.security.authentication.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService{private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt;private final AuthenticationManager auth;public AuthService(UserRepository users,PasswordEncoder encoder,JwtService jwt,AuthenticationManager auth){this.users=users;this.encoder=encoder;this.jwt=jwt;this.auth=auth;}@Transactional public AuthResponse register(RegisterRequest r){String e=r.email().toLowerCase();if(users.existsByEmail(e))throw new IllegalArgumentException("Email already registered");User u=User.builder().email(e).password(encoder.encode(r.password())).role(Role.USER).enabled(true).build();users.save(u);return response(u);}public AuthResponse login(LoginRequest r){String e=r.email().toLowerCase();auth.authenticate(new UsernamePasswordAuthenticationToken(e,r.password()));return response(users.findByEmail(e).orElseThrow());}private AuthResponse response(User u){return new AuthResponse(jwt.generate(u.getId(),u.getEmail(),u.getRole().name()),"Bearer",u.getId(),u.getEmail(),u.getRole().name());}}